export class Store {
    initialState;
    state;
    listeners = new Set();
    middlewares = [];
    constructor(initialState) {
        this.initialState = initialState;
        this.state = initialState;
    }
    getState() {
        return this.state;
    }
    getInitialState() {
        return this.initialState;
    }
    setState(nextState) {
        const runner = [...this.middlewares].reduceRight((next, middleware) => {
            return (state) => middleware(state, next);
        }, (state) => this.applyState(state));
        runner(nextState);
    }
    pushMiddleware(middleware) {
        this.middlewares.push(middleware);
    }
    unshiftMiddleware(middleware) {
        this.middlewares.unshift(middleware);
    }
    subscribe(listener) {
        this.listeners.add(listener);
        return () => {
            this.listeners.delete(listener);
        };
    }
    applyState(nextState) {
        const prevState = this.state;
        const resolvedState = typeof nextState === "function"
            ? nextState(prevState)
            : nextState;
        if (Object.is(prevState, resolvedState)) {
            return;
        }
        this.state = resolvedState;
        this.notify();
    }
    notify() {
        for (const listener of Array.from(this.listeners)) {
            listener();
        }
    }
}
